import{_ as t,o,c as a,a3 as r}from"./chunks/framework.Ki30n65y.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"reference/troubleshooting.md","filePath":"reference/troubleshooting.md"}'),n={name:"reference/troubleshooting.md"};function d(s,e,i,h,c,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="package-installs" tabindex="-1">Package installs <a class="header-anchor" href="#package-installs" aria-label="Permalink to &quot;Package installs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>What to do</th></tr></thead><tbody><tr><td><code>401 Unauthorized</code></td><td>The client sends no token, a wrong one, or an expired one.</td><td>Copy a fresh snippet from the <strong>Registry</strong> page. For CI, mint a new CI token.</td></tr><tr><td><code>403 Package blocked</code></td><td>A policy, the malware list or namespace protection blocked the version.</td><td>Read the reason in the message. Open <a href="/depgate/developers/package-check">Package check</a> for an allowed version, or <a href="/depgate/developers/waiver-requests">request a waiver</a>.</td></tr><tr><td><code>404</code> for an internal package</td><td>Namespace protection allows only internal remotes, and none of them has the package; or the client uses a repository without your internal remote.</td><td>Use the repository that includes your internal registry (often <code>all</code>). Check that the package is published internally.</td></tr><tr><td><code>502 Upstream … is unavailable</code></td><td>The upstream registry timed out or refused the connection. DepGate does not fall back to the next remote.</td><td>Check the remote with <strong>Test connection</strong> under <strong>Settings → Repositories</strong>, and the outbound proxy settings.</td></tr><tr><td><code>503 Upstream … is unavailable: circuit breaker open</code></td><td>The remote failed repeatedly, so DepGate stops calling it for a short time (<code>CIRCUIT_BREAKER_RESET_MS</code>, 10 seconds by default). <code>Retry-After</code> says when it tries again.</td><td>Retry after that time. If it keeps happening, check the remote as for a <code>502</code>.</td></tr><tr><td>Certificate errors (<code>UNABLE_TO_VERIFY_LEAF_SIGNATURE</code>, <code>SSL: CERTIFICATE_VERIFY_FAILED</code>, <code>PKIX path building failed</code>)</td><td>The client does not trust your CA.</td><td>See <a href="/depgate/install/https-and-networking#trusting-your-ca-in-package-clients">Trusting your CA in package clients</a>.</td></tr><tr><td>Go refuses the proxy URL</td><td><code>go</code> sends credentials only over HTTPS.</td><td>Put DepGate behind TLS.</td></tr><tr><td>A new release is not available</td><td>A release age policy (cool-down) blocks it.</td><td>It becomes available automatically. Package check shows when.</td></tr></tbody></table><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>What to do</th></tr></thead><tbody><tr><td>Forgot password</td><td>Use <strong>Forgot password?</strong> on the sign-in page. The link works once, for 60 minutes.</td></tr><tr><td>No invitation or reset email arrives</td><td>Check <strong>Settings → Email</strong> and send a test email. See <a href="/depgate/admin/email#troubleshooting">Email troubleshooting</a>.</td></tr><tr><td>The invitation link says <em>Link not valid</em></td><td>It was already used or has expired. Ask a Security user to resend it.</td></tr><tr><td>Everyone was signed out and registry tokens stopped working</td><td><code>JWT_SECRET</code> changed. Restore the previous value, or have everyone sign in again and copy new snippets.</td></tr><tr><td>Single sign-on refuses someone</td><td>The sign-in page says why. The <strong>Sign in</strong> entries in the <a href="/depgate/admin/audit-log">Audit Log</a> have the details, and <strong>Test sign-in</strong> on the provider shows what DepGate receives.</td></tr><tr><td>An identity provider is saved but turned off</td><td>DepGate could not reach it, or no sign-in domain is allowed. The reason is shown on the provider; fix it and turn the provider on.</td></tr></tbody></table><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>What to do</th></tr></thead><tbody><tr><td><code>docker compose up</code> stops with <em>Set … in .env</em></td><td>A required setting is missing. See <a href="/depgate/reference/configuration#required">Configuration → Required</a>.</td></tr><tr><td>The container never becomes healthy</td><td>Run <code>docker compose logs app</code>. Most often the database or Redis is unreachable from the container; with the bundled stack, use <code>host.docker.internal</code> as the host.</td></tr><tr><td><code>/readyz</code> reports an eviction policy other than <code>noeviction</code></td><td>Set <code>maxmemory-policy noeviction</code> on Redis, or use a separate <code>QUEUE_REDIS_URL</code>.</td></tr><tr><td>HTTPS does not start</td><td>Check that <code>certs/tls.crt</code> and <code>certs/tls.key</code> exist, match, and are readable by user ID 1000.</td></tr><tr><td>Client IP addresses in the ledger are all the proxy&#39;s</td><td>Set <code>TRUST_PROXY</code> to the number of proxies in front of DepGate.</td></tr><tr><td>A log streaming destination shows <strong>Auth failed</strong> or <strong>Retrying</strong></td><td>The row shows the destination&#39;s last answer. Fix the token or URL, then send a test event. Events are kept meanwhile.</td></tr></tbody></table><h2 id="data-feeds" tabindex="-1">Data feeds <a class="header-anchor" href="#data-feeds" aria-label="Permalink to &quot;Data feeds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>What to do</th></tr></thead><tbody><tr><td>A banner says EPSS data is stale</td><td>Open <strong>Settings → Jobs</strong>, check the last run of <strong>EPSS scores sync</strong>, then choose <strong>Run now</strong> on that row. Check outbound access to the EPSS feed.</td></tr><tr><td>The malware list is empty or old</td><td>Check the <strong>Malicious feed sync</strong> schedule under <strong>Settings → Jobs</strong>, and outbound access to github.com.</td></tr><tr><td>Package check shows <em>vulnerability data unavailable</em></td><td>DepGate could not reach OSV. Check outbound access to <code>api.osv.dev</code>.</td></tr></tbody></table><h2 id="getting-help" tabindex="-1">Getting help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting help&quot;">​</a></h2><p>When you report a problem, include the DepGate version, the relevant log lines (<code>docker compose logs app</code>), and for a blocked or failed install, the full error message and the time it happened, so the matching Decision Ledger entry can be found.</p>',11)])])}const u=t(n,[["render",d]]);export{p as __pageData,u as default};
